16	import { useEffect, useRef } from 'react';
17	import { supabase } from '@/integrations/supabase/client';
18	import { useMia, useMiaGlassBoxContext } from '@/shared/contexts/MiaContext';
19	import { useStore } from '@/shared/contexts/StoreContext';
