27	const STATUS_LABELS: Record<string, string> = {
28	  thinking: 'Raciocinando',
29	  calling_tools: 'Chamando tool',
30	  tools_done: 'Tool concluída',
31	  reflecting: 'Avaliando resultado',
32	  completed: 'Concluído',
33	  error: 'Erro',
34	};
