36	export function useMiaGlassBoxStreamBridge() {
37	  const {
38	    isStreaming,
39	    streamingStatus,
40	    executionSteps,
41	    agentRounds,
42	    thinkingBlocks,
43	    pendingConfirmation,
44	    activeTaskPlan,
45	  } = useMia();
46	
47	  const {
48	    miaModeEnabled,
49	    addWatchLogEntry,
50	    currentPageModel,
51	    highlightElement,
52	    clearHighlight,
