58	
59	  const { selectedStore } = useStore();
60	  // Ref pra ler store dentro de handlers de eventos sem re-criar effect
61	  const selectedStoreRef = useRef(selectedStore);
62	  useEffect(() => { selectedStoreRef.current = selectedStore; }, [selectedStore]);
63	
64	  // Refs pra detectar deltas sem re-emitir entries antigas
65	  const lastStreamingStatusRef = useRef<string | null>(null);
66	  const lastExecutionStepCountRef = useRef(0);
67	  const stepStatusesRef = useRef<Map<number, MiaExecutionStep['status']>>(new Map());
68	  const lastRoundIndexRef = useRef(-1);
69	  const lastThinkingCountRef = useRef(0);
70	  const wasStreamingRef = useRef(false);
71	
72	  // ── streamingStatus → watch log ─────────────────────────────
73	  // Também intercepta UI commands do backend (prefixo __MIA_UI__) e executa
74	  // como ações visuais (highlight, cursor, etc) sem adicionar ao watch log.
75	
76	  // OUVE eventos raw via CustomEvent (não dependente de React state).
77	  // useMia dispatch 'mia:sse-status' a cada SSE event individual — sem perda
78	  // por batch. Bridge processa tudo. Resolve bug onde planState.planId nunca
79	  // setava porque React batch suprimia plan_start em meio aos do_click.
80	  useEffect(() => {
81	    if (!miaModeEnabled) return;
82	    const handler = (e: Event) => {
83	      const text = (e as CustomEvent<string>).detail;
84	      if (!text) return;
85	      if (text.startsWith('__MIA_UI__')) {
86	        handleGlassBoxUiCommand(text.slice('__MIA_UI__'.length), {
87	          highlightElement,
88	          clearHighlight,
89	          moveCursor,
90	          addWatchLogEntry,
91	          recordAction,
92	          getSelectedStoreName: () => selectedStoreRef.current?.name ?? null,
93	        });
94	        return;
95	      }
96	      addWatchLogEntry({ status: 'in_progress', message: text });
97	    };
98	    window.addEventListener('mia:sse-status', handler);
99	    return () => window.removeEventListener('mia:sse-status', handler);
100	  }, [miaModeEnabled, addWatchLogEntry, highlightElement, clearHighlight, moveCursor, recordAction]);
101	
102	  // Mantém o effect antigo de streamingStatus desativado — todo trabalho
103	  // agora vai pelo CustomEvent. Sem isso teríamos double-processing.
104	  useEffect(() => {
105	    if (!miaModeEnabled || !streamingStatus) return;
106	    lastStreamingStatusRef.current = streamingStatus;
107	  }, [miaModeEnabled, streamingStatus]);
108	
109	  // ── executionSteps → watch log (com status updates) ─────────
110	
111	  useEffect(() => {
112	    if (!miaModeEnabled) return;
113	
114	    // Detecta novos steps
115	    if (executionSteps.length > lastExecutionStepCountRef.current) {
116	      const newSteps = executionSteps.slice(lastExecutionStepCountRef.current);
117	      newSteps.forEach((step) => {
118	        stepStatusesRef.current.set(step.index, step.status);
119	        addWatchLogEntry({
120	          status: stepToLogStatus(step.status),
121	          message: step.label,
122	          step_id: String(step.index),
123	          details: step.data,
124	        });
125	      });
126	      lastExecutionStepCountRef.current = executionSteps.length;
127	    }
128	
129	    // Detecta mudanças de status em steps existentes (running → success/error)
130	    executionSteps.forEach((step) => {
131	      const prevStatus = stepStatusesRef.current.get(step.index);
132	      if (prevStatus && prevStatus !== step.status) {
133	        stepStatusesRef.current.set(step.index, step.status);
134	        addWatchLogEntry({
135	          status: stepToLogStatus(step.status),
136	          message: step.error_message
137	            ? `${step.label} — ${step.error_message}`
138	            : `${step.label} (${step.status})`,
139	          step_id: String(step.index),
140	        });
141	
142	        // Confidence feedback no Page Model atual
143	        if (currentPageModel?.page_path) {
144	          if (step.status === 'success') {
145	            void boostPageConfidence(currentPageModel.page_path);
146	          } else if (step.status === 'error') {
147	            void lowerPageConfidence(currentPageModel.page_path);
148	          }
149	        }
150	      }
151	    });
152	  }, [miaModeEnabled, executionSteps, addWatchLogEntry, currentPageModel]);
153	
154	  // ── agentRounds → watch log (ReAct rounds) ─────────────────
155	
156	  useEffect(() => {
157	    if (!miaModeEnabled) return;
158	    if (agentRounds.length === 0) return;
159	
160	    const newRounds = agentRounds.slice(lastRoundIndexRef.current + 1);
161	    newRounds.forEach((round, i) => {
162	      const idx = lastRoundIndexRef.current + 1 + i;
163	      addWatchLogEntry({
164	        status: round.state === 'error' ? 'error'
165	          : round.state === 'completed' ? 'success'
166	          : 'in_progress',
167	        message: `[round ${round.round}] ${STATUS_LABELS[round.state] ?? round.state}${round.summary ? `: ${round.summary}` : ''}`,
168	        step_id: `round-${idx}`,
169	        details: round.tools && round.tools.length > 0
170	          ? { tools: round.tools.map((t) => `${t.name}${t.success === false ? '✗' : ''}`) }
171	          : undefined,
172	      });
173	    });
174	    lastRoundIndexRef.current = agentRounds.length - 1;
175	  }, [miaModeEnabled, agentRounds, addWatchLogEntry]);
176	
177	  // ── thinkingBlocks → watch log (raciocínio raw) ─────────────
178	
179	  useEffect(() => {
180	    if (!miaModeEnabled) return;
181	    if (thinkingBlocks.length === 0) return;
182	
183	    if (thinkingBlocks.length > lastThinkingCountRef.current) {
184	      const newThinking = thinkingBlocks.slice(lastThinkingCountRef.current);
185	      newThinking.forEach((tb) => {
186	        if (!tb.content || tb.content.trim().length === 0) return;
187	        // Resumo curto (evita encher o log com texto inteiro de raciocínio)
188	        const summary = tb.content.length > 140
189	          ? tb.content.slice(0, 137).trim() + '…'
190	          : tb.content.trim();
191	        addWatchLogEntry({
192	          status: 'info',
193	          message: `[thinking round ${tb.round}] ${summary}`,
194	          step_id: `thinking-${tb.round}`,
195	        });
196	      });
197	      lastThinkingCountRef.current = thinkingBlocks.length;
198	    }
199	  }, [miaModeEnabled, thinkingBlocks, addWatchLogEntry]);
