75	// Comprime histórico para localStorage: >10 msgs → mantém 6 recentes + 1 placeholder de compressão
76	function compressHistory(msgs: MiaChatMessage[]): MiaChatMessage[] {
77	  if (msgs.length <= 10) return msgs;
